pub fn pod_create(cfg: &Config, profile: &Profile) -> PodCreate {
    let on_volume = profile.network_volume_id.is_some();
    let (image, start, env) = match (&profile.job, &profile.recipe) {
        (Some(j), _) => (j.image.clone(), BOOTSTRAP_JOB, job_env()),
        (None, Some(r)) => match r.engine {
            Engine::Sglang => (r.image.clone(), BOOTSTRAP_SGLANG, engine_env(profile, r)),
        },
        (None, None) => (OLLAMA_IMAGE.to_string(), BOOTSTRAP, ollama_env(profile)),
    };
    PodCreate {
        name: pod_name(cfg, profile),
        image_name: image,
        gpu_type_ids: profile.gpu_type_ids.clone(),
        gpu_type_priority: "custom".into(),
        gpu_count: profile.gpu_count,
        cloud_type: "SECURE".into(),
        support_public_ip: true,
        ports: vec!["22/tcp".into()],
        container_disk_in_gb: profile.container_disk_gb,
        volume_in_gb: (!on_volume).then_some(profile.volume_gb),
        network_volume_id: profile.network_volume_id.clone(),
        volume_mount_path: "/workspace".into(),
        data_center_ids: profile.data_center_id.iter().cloned().collect(),
        allowed_cuda_versions: profile
            .effective_min_cuda()
            .as_deref()
            .and_then(cuda_at_least)
            .unwrap_or_default(),
        docker_entrypoint: vec!["bash".into(), "-c".into()],
        docker_start_cmd: vec![start.into()],
        env,
    }
}

/// The pod create for a plan: the profile's pod, but renting only from what the plan
/// recorded. The plan's GPU list is the one `offrig_plan` priced (filtered by price,
/// memory and fallback), and its CUDA floor is the one it was made with; a plan that
/// recorded neither (made before they existed) falls back to the profile's.
pub fn pod_create_for_plan(
    cfg: &Config,
    profile: &Profile,
    gpu_types: &[String],
    min_cuda: Option<&str>,
) -> PodCreate {
    let mut body = pod_create(cfg, profile);
    if !gpu_types.is_empty() {
        body.gpu_type_ids = gpu_types.to_vec();
    }
    if let Some(v) = min_cuda.and_then(cuda_at_least) {
        body.allowed_cuda_versions = v;
    }
    body

/// The live offrig pod for a profile in this session's lane, matched by its exact
/// lane name. Another lane's pod, or a plain-lane pod seen from a project lane,
/// is never this one.
pub fn current_pod(&self, profile: &Profile) -> Result<Option<Pod>> {
    let name = spec::pod_name(&self.cfg, profile);
    Ok(self
        .rp
        .list_pods()?
        .into_iter()
        .find(|p| p.name == name && p.desired_status != "TERMINATED"))
}

/// Refuse plans that cannot work before any money is spent.

/// Every live pod this session's lane owns, whatever its profile. A lane has one
/// ssh alias and one tunnel port, so it can serve one pod at a time.
pub fn lane_pods(&self) -> Result<Vec<Pod>> {
    Ok(self
        .rp
        .list_pods()?
        .into_iter()
        .filter(|p| self.cfg.owns_pod(&p.name) && p.desired_status != "TERMINATED")
        .collect())
}

/// Whether `profile` may launch in this lane: `Ok(Some(pod))` when the profile's own
/// pod is already up (launching again reuses it), `Ok(None)` when the lane is free,
/// and a refusal when the lane holds a pod of another profile. A second pod would
/// take the lane's one ssh alias and tunnel port from the first.
pub fn lane_guard(&self, profile: &Profile) -> Result<Option<Pod>> {
    let live = self.lane_pods()?;
    let mine = spec::pod_name(&self.cfg, profile);
    if let Some(p) = live.iter().find(|p| p.name == mine) {
        return Ok(Some(p.clone()));
    }
    if let Some(p) = live.first() {
        return Err(Error::Refused(format!(
            "lane {} has a live pod {} ({}); shut it down first",
            self.cfg.lane_tag.as_deref().unwrap_or("plain"),
            p.name,
            p.id
        )));
    }
    Ok(None)
}

