def edit_chars(pair: dict) -> int:
    """Characters changed (difflib, autojunk off: the larger side of each non-equal opcode)."""
    import difflib

    ops = [
        o
        for o in difflib.SequenceMatcher(None, pair["strong"], pair["flawed"], autojunk=False).get_opcodes()
