function usageLinesFor(verb) {
  if (!verb) return "";
  const prefix = `roleos ${verb}`;
  return helpCatalog()
    .split("\n")
    .filter((line) => {
      const trimmed = line.trimStart();
      return trimmed === prefix || trimmed.startsWith(`${prefix} `);
