    prompts = [p["prompt"] for p in pairs]
    strong = scorer.score_many(prompts, [p["strong"] for p in pairs])
    flawed = scorer.score_many(prompts, [p["flawed"] for p in pairs])
    return from_scores(strong, flawed, pairs)

def evaluate(scorer, pairs: list[dict], batch_size: int | None = None) -> dict:
    """Pairwise accuracy of `scorer.score_many(prompts, responses)` on the judge pairs.

    `batch_size` scores that many answers per forward pass. Unset, every answer goes in one pass,
    as on the 96 GB pod; a 32 GB card needs a few at a time."""
    prompts = [p["prompt"] for p in pairs]

    def scores(responses: list[str]) -> list[float]:
        if not batch_size:
            return scorer.score_many(prompts, responses)
        out: list[float] = []
        for i in range(0, len(responses), batch_size):
            out += scorer.score_many(prompts[i : i + batch_size], responses[i : i + batch_size])
        return out

    strong = scores([p["strong"] for p in pairs])
    flawed = scores([p["flawed"] for p in pairs])
    return from_scores(strong, flawed, pairs)

def apply_candidate(reply: str, answer: str) -> tuple[dict | None, str]:
    """The candidate applied by code, or None and why: no JSON, sentence not found, unchanged,
    self-flagging, or too different (character similarity below 0.85)."""
    data = extract_json_object(reply)
    if not data or not all(isinstance(data.get(k), str) for k in ("sentence", "edited")):
        return None, "no JSON candidate"
    for original, edited in (
        (data["sentence"], data["edited"]),
        (_restore_latex(data["sentence"]), _restore_latex(data["edited"])),
    ):
        original, edited = original.strip(), edited.strip()
        if not original or original not in answer:
            continue
        if edited == original:
            return None, "unchanged"
        flags = [m for m in SELF_FLAG_MARKERS if edited.lower().count(m) > original.lower().count(m)]
        if flags:
            return None, "self-flagging"
        flawed = answer.replace(original, edited, 1)
        if char_similarity(answer, flawed) < MIN_SIMILARITY:
            return None, "too different"
        chars, words = edit_size(answer, flawed)
        return {
            "reasoning": data.get("reasoning", ""),
            "sentence": original,
            "edited_sentence": edited,
            "kind": data.get("kind", ""),
            "flawed": flawed,
            "edit_chars": chars,
            "edit_words": words,
        }, "ok"
    return None, "sentence not in the answer"

pub fn pod_create(cfg: &Config, profile: &Profile) -> PodCreate {
    let on_volume = profile.network_volume_id.is_some();
    let (image, start, env) = match (&profile.job, &profile.recipe) {
        (Some(j), _) => (j.image.clone(), BOOTSTRAP_JOB, job_env()),
        (None, Some(r)) => match r.engine {
            Engine::Sglang => (r.image.clone(), BOOTSTRAP_SGLANG, engine_env(profile, r)),
        },
        (None, None) => (OLLAMA_IMAGE.to_string(), BOOTSTRAP, ollama_env(profile)),
    };
    PodCreate {
        name: pod_name(cfg, profile),
        image_name: image,
        gpu_type_ids: profile.gpu_type_ids.clone(),
        gpu_type_priority: "custom".into(),
        gpu_count: profile.gpu_count,
        cloud_type: "SECURE".into(),
        support_public_ip: true,
        ports: vec!["22/tcp".into()],
        container_disk_in_gb: profile.container_disk_gb,
        volume_in_gb: (!on_volume).then_some(profile.volume_gb),
        network_volume_id: profile.network_volume_id.clone(),
        volume_mount_path: "/workspace".into(),
        data_center_ids: profile.data_center_id.iter().cloned().collect(),
        allowed_cuda_versions: profile
            .effective_min_cuda()
            .as_deref()
            .and_then(cuda_at_least)
            .unwrap_or_default(),
        docker_entrypoint: vec!["bash".into(), "-c".into()],
        docker_start_cmd: vec![start.into()],
        env,
    }
}

/// The pod create for a plan: the profile's pod, but renting only from what the plan
/// recorded. The plan's GPU list is the one `offrig_plan` priced (filtered by price,
/// memory and fallback), and its CUDA floor is the one it was made with; a plan that
/// recorded neither (made before they existed) falls back to the profile's.
pub fn pod_create_for_plan(
    cfg: &Config,
    profile: &Profile,
    gpu_types: &[String],
    min_cuda: Option<&str>,
) -> PodCreate {
    let mut body = pod_create(cfg, profile);
    if !gpu_types.is_empty() {
        body.gpu_type_ids = gpu_types.to_vec();
    }
    if let Some(v) = min_cuda.and_then(cuda_at_least) {
        body.allowed_cuda_versions = v;
    }
    body

