) -> tuple[list[dict], dict]:
    """Up to `per_answer` paraphrases per strong answer, each on a different sentence, within its
    size cap (twice the answer's own error edit, at least 8 characters, or `max_chars` if given) and
    past the lexical guard; the pairs (original as "strong", reworded as "flawed"). Each paraphrase
    gets up to `rounds` attempts; the round that produced it is recorded."""
    held = [(it["topic"], it["prompt"]) for it in items]
    strong = [it["strong"] for it in items]
    outcomes: dict[str, int] = {}
    first: dict = {}
    for r in range(1, rounds + 1):
        todo = [(i, FIRST) for i, it in enumerate(items) if it["prompt_id"] not in first]
        if not todo:
            break
        for p in _round(backend, system, items, held, strong, todo, "p1", r, max_chars, outcomes):
            first.setdefault(p["prompt_id"], p)
    pairs = list(first.values())
    second: dict = {}
    dropped_same_sentence = 0
    if per_answer > 1:
        index = {it["prompt_id"]: i for i, it in enumerate(items)}
        for r in range(1, rounds + 1):
            todo = [(index[pid], avoid(sentences(p)[0])) for pid, p in first.items() if pid not in second]
            if not todo:
                break
            for p in _round(backend, system, items, held, strong, todo, "p2", r, max_chars, outcomes):
                if overlaps(p, first[p["prompt_id"]]):
                    dropped_same_sentence += 1
                    continue
                second.setdefault(p["prompt_id"], p)
        pairs += list(second.values())

impl Ollama {
    /// Embed `inputs` in one `/api/embed` call, one vector per input in order. With
    /// `cpu_only` the request carries `num_gpu: 0` so the model never loads on a GPU.
    /// A model the server does not have is reported with the pull line.
    pub fn embed(&self, model: &str, inputs: &[String], cpu_only: bool) -> Result<Vec<Vec<f32>>> {
        let what = "embed";
        let mut body = json!({ "model": model, "input": inputs });
        if cpu_only {
            body["options"] = json!({ "num_gpu": 0 });
        }
        let v = self.post("/api/embed", &body, what).map_err(|e| match &e {
            Error::Ollama(m) if m.contains("http 404") => Error::Refused(format!(
                "the embedding model {model} is not installed on {}; run `ollama pull {model}` against that host",
                self.base
            )),
            _ => e,
        })?;
        let rows = v["embeddings"]
            .as_array()
            .ok_or_else(|| Error::Ollama(format!("{what}: the reply carried no embeddings")))?;
        let out: Vec<Vec<f32>> = rows
            .iter()
            .map(|r| {
                r.as_array()
                    .map(|a| a.iter().map(|n| n.as_f64().unwrap_or(0.0) as f32).collect())
                    .unwrap_or_default()
            })
            .collect();
        let dim = out.first().map_or(0, Vec::len);
        if out.len() != inputs.len() || dim == 0 || out.iter().any(|r| r.len() != dim) {
            return Err(Error::Ollama(format!(
                "{what}: expected {} vectors of one size, got {}",
                inputs.len(),
                out.len()
            )));
        }
        Ok(out)
    }

export function suggestPack(content) {
  const lower = content.toLowerCase();
  const scores = {};

  for (const [packName, keywords] of Object.entries(PACK_KEYWORDS)) {
    let score = 0;
    for (const kw of keywords) {
      if (lower.includes(kw)) score++;
    }
    if (score > 0) scores[packName] = score;
  }

  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  if (sorted.length === 0) return null;

  const [topPack, topScore] = sorted[0];
  const confidence = topScore >= 3 ? "high" : topScore >= 2 ? "medium" : "low";

  return { pack: topPack, confidence, scores };
}

export function suggestPack(content, options = {}) {
  const lower = content.toLowerCase();
  const scores = {};

  for (const [packName, keywords] of Object.entries(PACK_KEYWORDS)) {
    let score = 0;
    for (const kw of keywords) {
      if (lower.includes(kw)) score++;
    }
    if (score > 0) scores[packName] = score;
  }

  const snap = calibrationSnapshot(options);
  const adjusted = {};
  for (const name of Object.keys(scores)) {
    const row = snap.evidence.find((item) => item.pack === name);
    const boost = row && row.status === "measured" ? row.boost : 0;
    adjusted[name] = scores[name] + boost;
  }

  const sorted = Object.entries(adjusted).sort((a, b) => b[1] - a[1]);
  if (sorted.length === 0) return null;

  const topPack = sorted[0][0];
  const keywordScore = scores[topPack];
  const confidence = keywordScore >= 3 ? "high" : keywordScore >= 2 ? "medium" : "low";

  return {
    pack: topPack,
    confidence,
    scores,
    evidence: snap.evidence,
    calibration: snap.disabled ? "off" : (snap.outcomes.length ? "on" : "empty"),
    calibrationText: snap.text,
  };
}

